def count_pairs_summing_to(nums, target):
    cnt = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] + nums[j] == target:
                cnt += 1
    return cnt

def is_valid_coupon_code(s):
    if len(s) != 8 or not all(c.isalnum() and (c.isdigit() or c.isupper()) for c in s):
        return False
    has_letter = any(c.isalpha() for c in s)
    has_digit = any(c.isdigit() for c in s)
    return has_letter and has_digit

def integer_nth_root(n, k):
    if n == 0:
        return 0
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid ** k <= n:
            lo = mid
        else:
            hi = mid - 1
    return lo

def transpose_dict_of_lists(d):
