def bucket_sort_by_decade(nums):
    from collections import defaultdict
    groups = defaultdict(list)
    for v in nums:
        decade = (v // 10) * 10
        groups[decade].append(v)
    return {d: sorted(groups[d]) for d in sorted(groups)}

def pluralize_count(word, n):
    if n == 1:
        form = word
    else:
        if word.endswith(('s', 'x', 'z', 'ch', 'sh')):
            form = word + 'es'
        elif word.endswith('y') and len(word) > 1 and word[-2] not in 'aeiou':
            form = word[:-1] + 'ies'
        else:
            form = word + 's'
    return f"{n} {form}"

def longest_run_above_threshold(lst, t):
    best = 0
    cur = 0
    for x in lst:
        if x >= t:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

def meets_strict_password_policy(s):
    if len(s) < 10:
        return False
    if any(c.isspace() for c in s):
        return False
    specials = set('!@#$%^&*')
    return (any(c.isupper() for c in s) and any(c.islower() for c in s)
            and any(c.isdigit() for c in s) and any(c in specials for c in s))

