def compress_to_tuples(s):
    if not s:
        return []
    result = []
    prev = s[0]
    count = 1
    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append((prev, count))
            prev = c
            count = 1
    result.append((prev, count))
    return result

