def distinct_prime_factors(n):
    n = abs(n)
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def bucket_sort_by_sign(nums):
    neg = sorted(n for n in nums if n < 0)
    zero = sorted(n for n in nums if n == 0)
    pos = sorted(n for n in nums if n > 0)
    return {'negative': neg, 'zero': zero, 'positive': pos}

