def most_common_n_chars(s, n):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ordered[:n]

def most_common_word_length(words):
    counts = {}
    for w in words:
        counts[len(w)] = counts.get(len(w), 0) + 1
    best = max(counts.values())
    cands = [l for l, c in counts.items() if c == best]
    return min(cands)
